/**
 * @file Breadcrumb FSM (Finite State Machine)
 * @description State machine for managing Breadcrumb expand/collapse behavior
 *
 * ## State Diagram
 *
 * ```
 *     ┌─────────────────────────────────────────┐
 *     │                                         │
 *     │  RESET_FROM_PROPS (controlledExpanded)  │
 *     │                                         │
 *     ▼                                         │
 * ┌───────────┐    EXPAND (click)         ┌─────┴─────┐
 * │ collapsed │ ─────────────────────────▶│  expanded │
 * └───────────┘                           └───────────┘
 *     ▲                                         │
 *     │                                         │
 *     └─── RESET_FROM_PROPS (!controlledExpanded) ───┘
 * ```
 *
 * ## States
 * - `collapsed`: Breadcrumb is showing ellipsis (default)
 * - `expanded`: Breadcrumb is showing all items
 *
 * ## Events
 * - `EXPAND`: User clicks ellipsis to show all items
 * - `RESET_FROM_PROPS`: Sync state with controlled prop
 */

// ============================================================================
// State Types
// ============================================================================

/**
 * Possible visual states for the Breadcrumb expand behavior
 */
export type BreadcrumbExpandState = 'collapsed' | 'expanded';

/**
 * Complete FSM state for Breadcrumb
 */
export interface BreadcrumbFSMState {
  /** Current expand/collapse state */
  expandState: BreadcrumbExpandState;
  /** Whether the expanded state is controlled externally */
  isControlled: boolean;
}

// ============================================================================
// Event Types
// ============================================================================

/**
 * User clicks the ellipsis button to expand
 */
export interface ExpandEvent {
  type: 'EXPAND';
}

/**
 * Sync state from controlled prop changes
 */
export interface ResetFromPropsEvent {
  type: 'RESET_FROM_PROPS';
  payload: {
    controlledExpanded: boolean | undefined;
  };
}

/**
 * Union of all possible FSM events
 */
export type BreadcrumbFSMEvent = ExpandEvent | ResetFromPropsEvent;

// ============================================================================
// Initial State Factory
// ============================================================================

/**
 * Creates the initial FSM state based on props
 *
 * @param controlledExpanded - External controlled expanded state
 * @returns Initial FSM state
 *
 * @example
 * ```tsx
 * // Uncontrolled - starts collapsed
 * const state = createInitialBreadcrumbFSMState(undefined);
 * // { expandState: 'collapsed', isControlled: false }
 *
 * // Controlled - starts expanded
 * const state = createInitialBreadcrumbFSMState(true);
 * // { expandState: 'expanded', isControlled: true }
 * ```
 */
export function createInitialBreadcrumbFSMState(
  controlledExpanded: boolean | undefined
): BreadcrumbFSMState {
  const isControlled = controlledExpanded !== undefined;

  return {
    expandState: controlledExpanded ? 'expanded' : 'collapsed',
    isControlled,
  };
}

// ============================================================================
// State Transition Logic
// ============================================================================

/**
 * Pure reducer function for Breadcrumb FSM state transitions
 *
 * ## Transition Rules
 *
 * | Current State | Event           | Next State | Condition               |
 * |---------------|-----------------|------------|-------------------------|
 * | collapsed     | EXPAND          | expanded   | !isControlled           |
 * | collapsed     | EXPAND          | collapsed  | isControlled (no-op)    |
 * | collapsed     | RESET_FROM_PROPS| expanded   | controlledExpanded=true |
 * | expanded      | RESET_FROM_PROPS| collapsed  | controlledExpanded=false|
 * | any           | RESET_FROM_PROPS| synced     | Updates isControlled    |
 *
 * @param state - Current FSM state
 * @param event - Event to process
 * @returns New FSM state (immutable)
 */
export function breadcrumbFSMReducer(
  state: BreadcrumbFSMState,
  event: BreadcrumbFSMEvent
): BreadcrumbFSMState {
  switch (event.type) {
    case 'EXPAND': {
      // In controlled mode, parent manages state via RESET_FROM_PROPS
      // We still transition to expanded in uncontrolled mode
      if (state.isControlled) {
        return state;
      }

      // Already expanded - no change needed
      if (state.expandState === 'expanded') {
        return state;
      }

      return {
        ...state,
        expandState: 'expanded',
      };
    }

    case 'RESET_FROM_PROPS': {
      const { controlledExpanded } = event.payload;
      const isControlled = controlledExpanded !== undefined;
      const newExpandState: BreadcrumbExpandState = controlledExpanded ? 'expanded' : 'collapsed';

      // Only return new state if something changed
      if (state.isControlled === isControlled && state.expandState === newExpandState) {
        return state;
      }

      return {
        expandState: newExpandState,
        isControlled,
      };
    }

    default: {
      // Exhaustive check - TypeScript will error if a case is missing
      const _exhaustiveCheck: never = event;
      return _exhaustiveCheck;
    }
  }
}

// ============================================================================
// State Predicates
// ============================================================================

/**
 * Check if breadcrumb is in collapsed state
 */
export function isCollapsed(state: BreadcrumbFSMState): boolean {
  return state.expandState === 'collapsed';
}

/**
 * Check if breadcrumb is in expanded state
 */
export function isExpanded(state: BreadcrumbFSMState): boolean {
  return state.expandState === 'expanded';
}

// ============================================================================
// Event Creators
// ============================================================================

/**
 * Create an EXPAND event
 */
export function expandEvent(): ExpandEvent {
  return { type: 'EXPAND' };
}

/**
 * Create a RESET_FROM_PROPS event
 */
export function resetFromPropsEvent(controlledExpanded: boolean | undefined): ResetFromPropsEvent {
  return {
    type: 'RESET_FROM_PROPS',
    payload: { controlledExpanded },
  };
}

import {
  forwardRef,
  type MouseEvent,
  memo,
  useCallback,
  useEffect,
  useMemo,
  useReducer,
} from 'react';

import { cn } from '../../utils';
import { isExternalUrl } from '../../utils/types';
import { isSafeHref } from '../../utils/validation';

import {
  breadcrumbFSMReducer,
  createInitialBreadcrumbFSMState,
  expandEvent,
  isExpanded as isFSMExpanded,
  resetFromPropsEvent,
} from './Breadcrumb.fsm';

import type { BreadcrumbItemData, BreadcrumbItemProps, BreadcrumbProps } from './Breadcrumb.types';

// =============================================================================
// BreadcrumbItem Component
// =============================================================================

/**
 * BreadcrumbItem component — individual breadcrumb link or text.
 * Validates href for dangerous protocols and adds rel attributes for external links.
 *
 * @see https://getbootstrap.com/docs/5.3/components/breadcrumb/
 */
const BreadcrumbItemComponent = forwardRef<HTMLLIElement, BreadcrumbItemProps>(
  function BreadcrumbItem(
    {
      children,
      href,
      icon,
      active = false,
      onClick,
      className = '',
      style,
      linkAs: LinkComponent,
      maxLabelWidth,
      'data-testid': dataTestId,
      'data-test': dataTest,
    },
    ref
  ) {
    const itemClasses = useMemo(
      () => cn('breadcrumb-item', active && 'active', className),
      [active, className]
    );

    // Validate href:
    // - undefined/null → no link (text-only item)
    // - unsafe protocol → fallback to '#' (blocks XSS, still renders <a>)
    // - safe href → pass through
    const hasHref = href != null;
    const safeHref = hasHref ? (isSafeHref(href) ? href : '#') : undefined;
    const isExternal = safeHref && safeHref !== '#' ? isExternalUrl(safeHref) : false;
    const relAttribute = isExternal ? 'noopener noreferrer' : undefined;

    const handleClick = (e: MouseEvent<HTMLAnchorElement>): void => {
      if (onClick) {
        e.preventDefault();
        onClick();
      }
    };

    // Truncation styles for long labels
    const truncateStyle = maxLabelWidth
      ? ({
          display: 'inline-block',
          maxWidth: maxLabelWidth,
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          whiteSpace: 'nowrap',
          verticalAlign: 'bottom',
        } as React.CSSProperties)
      : undefined;

    const labelContent = truncateStyle ? (
      <span style={truncateStyle} title={typeof children === 'string' ? children : undefined}>
        {children}
      </span>
    ) : (
      children
    );

    const content = (
      <>
        {icon && (
          <span className="me-1" aria-hidden="true">
            {icon}
          </span>
        )}
        {labelContent}
      </>
    );

    const renderContent = (): React.ReactNode => {
      if (active) {
        return content;
      }

      // Render link only when there is a valid href or click handler
      if (safeHref || onClick) {
        if (LinkComponent) {
          return (
            <LinkComponent
              href={safeHref ?? '#'}
              onClick={onClick ? handleClick : undefined}
              rel={relAttribute}
            >
              {content}
            </LinkComponent>
          );
        }

        return (
          <a href={safeHref ?? '#'} onClick={onClick ? handleClick : undefined} rel={relAttribute}>
            {content}
          </a>
        );
      }

      return content;
    };

    return (
      <li
        ref={ref}
        className={itemClasses}
        style={style}
        aria-current={active ? 'page' : undefined}
        data-testid={dataTestId}
        data-test={dataTest}
      >
        {renderContent()}
      </li>
    );
  }
);

BreadcrumbItemComponent.displayName = 'BreadcrumbItem';

export const BreadcrumbItem = memo(BreadcrumbItemComponent);
BreadcrumbItem.displayName = 'BreadcrumbItem';

// =============================================================================
// Schema.org JSON-LD
// =============================================================================

/**
 * Generates Schema.org BreadcrumbList structured data for SEO.
 * @see https://schema.org/BreadcrumbList
 * @see https://developers.google.com/search/docs/appearance/structured-data/breadcrumb
 */
function generateStructuredData(items: BreadcrumbItemData[]): string {
  const itemListElement = items.map((item, index) => ({
    '@type': 'ListItem',
    position: index + 1,
    name: typeof item.label === 'string' ? item.label : `Item ${index + 1}`,
    ...(item.href ? { item: item.href } : {}),
  }));

  return JSON.stringify({
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement,
  });
}

// =============================================================================
// Helper: is separator a plain string?
// =============================================================================

function isStringSeparator(separator: React.ReactNode): separator is string {
  return typeof separator === 'string';
}

// =============================================================================
// Breadcrumb Component
// =============================================================================

export const Breadcrumb = memo(
  forwardRef<HTMLElement, BreadcrumbProps>(function Breadcrumb(
    {
      items,
      children,
      separator = '/',
      maxItems,
      itemsAfterCollapse = 1,
      itemsBeforeCollapse = 1,
      onExpand,
      expanded: controlledExpanded,
      expandText = 'Show hidden breadcrumbs',
      linkAs,
      maxLabelWidth,
      renderCollapsedItems,
      structuredData = false,
      'aria-label': ariaLabel,
      'aria-labelledby': ariaLabelledBy,
      className = '',
      style,
      id,
      'data-testid': dataTestId,
      'data-test': dataTest,
    },
    ref
  ) {
    // FSM-based state management for expand/collapse
    const [fsmState, dispatch] = useReducer(
      breadcrumbFSMReducer,
      controlledExpanded,
      createInitialBreadcrumbFSMState
    );

    // Sync FSM state when controlled prop changes
    useEffect(() => {
      dispatch(resetFromPropsEvent(controlledExpanded));
    }, [controlledExpanded]);

    const isExpanded = isFSMExpanded(fsmState);

    const handleEllipsisClick = useCallback((): void => {
      dispatch(expandEvent());
      onExpand?.();
    }, [onExpand]);

    // Accessible label with fallback chain
    const navAriaLabel = useMemo(() => {
      if (ariaLabelledBy) {return undefined;}
      if (ariaLabel) {return ariaLabel;}
      if (id) {return `Breadcrumb ${id}`;}
      return 'Breadcrumb';
    }, [ariaLabel, ariaLabelledBy, id]);

    // Separator handling: string → CSS variable; ReactNode → inline rendering
    const useInlineSeparator = !isStringSeparator(separator);

    const separatorStyle = useMemo<React.CSSProperties | undefined>(() => {
      if (useInlineSeparator) {
        // Hide the CSS-generated separator when using inline ReactNode separators
        return { '--bs-breadcrumb-divider': "''" } as React.CSSProperties;
      }
      return separator !== '/'
        ? ({ '--bs-breadcrumb-divider': `'${separator}'` } as React.CSSProperties)
        : undefined;
    }, [separator, useInlineSeparator]);

    // Render items (data-driven mode)
    const renderedItems = useMemo(() => {
      if (!items || items.length === 0) {return null;}

      const shouldCollapse = maxItems != null && items.length > maxItems && !isExpanded;

      let displayItems: (BreadcrumbItemData | 'ellipsis')[] = items;
      let hiddenItems: BreadcrumbItemData[] = [];

      if (shouldCollapse) {
        const beforeItems = items.slice(0, itemsBeforeCollapse);
        const afterItems = items.slice(items.length - itemsAfterCollapse);
        hiddenItems = items.slice(itemsBeforeCollapse, items.length - itemsAfterCollapse);
        displayItems = [...beforeItems, 'ellipsis', ...afterItems];
      }

      const elements: React.ReactNode[] = [];

      displayItems.forEach((item, index) => {
        // Insert inline separator before every item except the first
        if (useInlineSeparator && index > 0) {
          elements.push(
            <li
              key={`sep-${index}`}
              className="breadcrumb-separator"
              aria-hidden="true"
              role="presentation"
            >
              {separator}
            </li>
          );
        }

        if (item === 'ellipsis') {
          const ellipsisContent = renderCollapsedItems ? (
            renderCollapsedItems(hiddenItems)
          ) : (
            <button
              type="button"
              className="btn btn-link p-0 border-0 text-decoration-none"
              onClick={handleEllipsisClick}
              aria-label={expandText}
              aria-expanded={isExpanded}
            >
              …
            </button>
          );

          elements.push(
            <li key="ellipsis" className="breadcrumb-item">
              {ellipsisContent}
            </li>
          );
          return;
        }

        const isLast = index === displayItems.length - 1;
        const isActive = item.active ?? isLast;
        const safeItemHref = item.href != null
          ? (isSafeHref(item.href) ? item.href : '#')
          : undefined;

        elements.push(
          <BreadcrumbItem
            key={item.id ?? index}
            href={safeItemHref}
            icon={item.icon}
            active={isActive}
            onClick={item.onClick}
            linkAs={linkAs}
            maxLabelWidth={maxLabelWidth}
          >
            {item.label}
          </BreadcrumbItem>
        );
      });

      return (
        <ol className="breadcrumb mb-0" style={separatorStyle}>
          {elements}
        </ol>
      );
    }, [
      items,
      maxItems,
      itemsAfterCollapse,
      itemsBeforeCollapse,
      isExpanded,
      separatorStyle,
      linkAs,
      handleEllipsisClick,
      expandText,
      renderCollapsedItems,
      maxLabelWidth,
      useInlineSeparator,
      separator,
    ]);

    // Render children (compound component mode)
    const renderedChildren = useMemo(() => {
      if (!children) {return null;}

      // For inline separators in compound mode, we can't auto-insert between children
      // because we don't control the children structure — use CSS variable approach
      return (
        <ol className="breadcrumb mb-0" style={separatorStyle}>
          {children}
        </ol>
      );
    }, [children, separatorStyle]);

    // Schema.org JSON-LD
    const jsonLd = structuredData && items && items.length > 0
      ? generateStructuredData(items)
      : null;

    return (
      <>
        {jsonLd && (
          <script
            type="application/ld+json"
            dangerouslySetInnerHTML={{ __html: jsonLd }}
          />
        )}
        <nav
          ref={ref}
          aria-label={navAriaLabel}
          aria-labelledby={ariaLabelledBy}
          className={className || undefined}
          style={style}
          id={id}
          data-visual-state={fsmState.expandState}
          data-testid={dataTestId}
          data-test={dataTest}
        >
          {items ? renderedItems : renderedChildren}
        </nav>
      </>
    );
  })
);

Breadcrumb.displayName = 'Breadcrumb';

// =============================================================================
// Exports
// =============================================================================

export type { BreadcrumbItemData, BreadcrumbItemProps, BreadcrumbProps };

import type { CSSProperties, ReactNode } from 'react';

/**
 * Breadcrumb item configuration (data-driven mode)
 */
export interface BreadcrumbItemData {
  /**
   * Unique identifier for the item
   */
  id?: string;

  /**
   * Display label
   */
  label: ReactNode;

  /**
   * URL for the breadcrumb link
   * If not provided, renders as text (current page)
   */
  href?: string;

  /**
   * Icon to display before the label
   */
  icon?: ReactNode;

  /**
   * Whether this is the current/active page
   * @default false
   */
  active?: boolean;

  /**
   * Click handler (alternative to href for SPA routing)
   */
  onClick?: () => void;
}

/**
 * BreadcrumbItem component props (compound component mode)
 */
export interface BreadcrumbItemProps {
  /**
   * Item content
   */
  children: ReactNode;

  /**
   * URL for the breadcrumb link
   */
  href?: string;

  /**
   * Icon to display before the label
   */
  icon?: ReactNode;

  /**
   * Whether this is the current/active page
   * @default false
   */
  active?: boolean;

  /**
   * Click handler
   */
  onClick?: () => void;

  /**
   * Additional CSS class names
   */
  className?: string;

  /**
   * Inline styles
   */
  style?: CSSProperties;

  /**
   * Custom link component (for router integration)
   * @example
   * ```tsx
   * import { Link } from 'react-router-dom';
   * <BreadcrumbItem linkAs={Link} href="/home">Home</BreadcrumbItem>
   * ```
   */
  linkAs?: React.ElementType;

  /**
   * Truncate long labels with ellipsis at this max width (CSS value)
   * @example '120px', '10em'
   */
  maxLabelWidth?: string;

  /** Test ID attribute */
  'data-testid'?: string;

  /** Test attribute */
  'data-test'?: string;
}

/**
 * Breadcrumb container props
 */
export interface BreadcrumbProps {
  /**
   * Breadcrumb items to render (data-driven mode)
   */
  items?: BreadcrumbItemData[];

  /**
   * Children (compound component mode — alternative to items prop)
   */
  children?: ReactNode;

  /**
   * Custom separator between items.
   * - String values use Bootstrap's `--bs-breadcrumb-divider` CSS variable
   * - ReactNode values render inline between items (replaces CSS separator)
   * @default '/'
   */
  separator?: ReactNode;

  /**
   * Maximum number of items to show before collapsing.
   * When exceeded, shows first items, ellipsis, and last items.
   */
  maxItems?: number;

  /**
   * Number of items to show after ellipsis when collapsed
   * @default 1
   */
  itemsAfterCollapse?: number;

  /**
   * Number of items to show before ellipsis when collapsed
   * @default 1
   */
  itemsBeforeCollapse?: number;

  /**
   * Callback when ellipsis is clicked to expand
   */
  onExpand?: () => void;

  /**
   * Whether the breadcrumb is currently expanded (controlled mode)
   * @default false
   */
  expanded?: boolean;

  /**
   * Accessible label for the expand/ellipsis button
   * @default 'Show hidden breadcrumbs'
   */
  expandText?: string;

  /**
   * Custom link component for all items (router integration)
   */
  linkAs?: React.ElementType;

  /**
   * Truncate long item labels with ellipsis at this max width (CSS value).
   * Applies to all items. Override per-item via BreadcrumbItem's maxLabelWidth.
   * @example '150px', '12em'
   */
  maxLabelWidth?: string;

  /**
   * Render prop for collapsed items — receives the hidden items array.
   * Use to render a dropdown or popover showing collapsed breadcrumbs.
   *
   * @example
   * ```tsx
   * <Breadcrumb
   *   items={items}
   *   maxItems={4}
   *   renderCollapsedItems={(hiddenItems) => (
   *     <Dropdown items={hiddenItems.map(i => ({ label: i.label, href: i.href }))} />
   *   )}
   * />
   * ```
   */
  renderCollapsedItems?: (hiddenItems: BreadcrumbItemData[]) => ReactNode;

  /**
   * Generate Schema.org BreadcrumbList JSON-LD structured data.
   * When true, renders a `<script type="application/ld+json">` tag.
   * Only works with the `items` prop (data-driven mode).
   * @default false
   */
  structuredData?: boolean;

  /**
   * Accessible label for the navigation
   * @default 'Breadcrumb'
   */
  'aria-label'?: string;

  /**
   * ID reference to an element that labels the navigation
   */
  'aria-labelledby'?: string;

  /**
   * Additional CSS class names
   */
  className?: string;

  /**
   * Inline styles
   */
  style?: CSSProperties;

  /**
   * ID attribute
   */
  id?: string;

  /** Test ID attribute */
  'data-testid'?: string;

  /** Test attribute */
  'data-test'?: string;
}

/**
 * Breadcrumb component exports
 *
 * @module Breadcrumb
 */

export { Breadcrumb, BreadcrumbItem } from './Breadcrumb';
export type {
  BreadcrumbExpandState,
  BreadcrumbFSMEvent,
  BreadcrumbFSMState,
  ExpandEvent,
  ResetFromPropsEvent,
} from './Breadcrumb.fsm';

// FSM exports for advanced usage
export {
  breadcrumbFSMReducer,
  createInitialBreadcrumbFSMState,
  expandEvent,
  isCollapsed,
  isExpanded,
  resetFromPropsEvent,
} from './Breadcrumb.fsm';
export type { BreadcrumbItemData, BreadcrumbItemProps, BreadcrumbProps } from './Breadcrumb.types';
